export async function invokeHarness(endpoint, job, options = {}) {
 const dir = mkdtempSync(join(tmpdir(), "inference-fabric-"));
 const packet = join(dir, "packet.json");
 writeFileSync(packet, JSON.stringify({ model: endpoint.model, messages: job.messages, ...(job.maxTokens ? { "max-tokens": job.maxTokens } : {}) }));
 try { /* child invocation */ const record = JSON.parse(Buffer.concat(out).toString());
 if (record.outcome === "refusal") throw new Error(record.refusal?.grounds ?? "harness refusal");
 return { text: record.completion?.text ?? "", usage: record.completion?.usage ?? null, cost: record.cost ?? null };
 } finally { rmSync(dir, { recursive: true, force: true }); }
}
